import{z as A,x as m,o,c as S,q as r,j as n,D as l,d as s,s as E,S as t,b as a}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"SenseVoice","description":"","frontmatter":{"title":"SenseVoice","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sensevoice-small.md","filePath":"llm/sensevoice-small.md","lastUpdated":1791413859000}'),d={name:"llm/sensevoice-small.md"};function p(c,e,B,C,h,u){const i=m("Mermaid");return o(),S("div",null,[e[2]||(e[2]=r('<h1 id="sensevoice" tabindex="-1">SenseVoice <a class="header-anchor" href="#sensevoice" aria-label="Permalink to &quot;SenseVoice&quot;">​</a></h1><div class="epigraph"><p>SenseVoice-Small 用非自回归端到端结构做五语种低延迟识别，速度超过 Whisper-small 五倍、Whisper-large 十五倍以上；SenseVoice-Large 则把高精度 ASR 做到五十种以上语言。</p><footer>—— Tongyi SpeechTeam, FunAudioLLM, arXiv:2407.04051</footer></div><p>FunAudioLLM（阿里通义语音，arXiv:2407.04051）把语音交互拆成理解与生成两块：理解是 <strong>SenseVoice</strong>，生成是 CosyVoice。SenseVoice 要在一次前向里给出转写、语种、情感与音频事件，而不是串四个模型。开源落地的是 <strong>SenseVoice-Small</strong>（ModelScope <code>iic/SenseVoiceSmall</code>，Hugging Face <code>FunAudioLLM/SenseVoiceSmall</code>），面向中、英、粤、日、韩；Large 做 50+ 语种高精度，报告描述架构但权重策略以当时仓库为准。FunASR 工具包把 Small 标到约 234M，并可与 FSMN-VAD、标点、说话人模型拼接。本篇写 FunAudioLLM 报告与官方仓库已写明的理解模型，不把 Qwen2-Audio 的 LLM 解码器画进来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Whisper 一类自回归 ASR 把音频编码后再逐 token 出字，准确、多语，但延迟随字数涨，且默认不管情绪、掌声、背景乐。对话助手却经常需要：用户是不是在生气、有没有笑声、这句话要不要做 ITN。若外挂情感模型与事件检测，时间戳与标签还要对齐三次。SenseVoice 把问题收成：<strong>同一套语音基础模型，用特殊 token 指定任务，非自回归则保延迟，自回归大号则保语种覆盖。</strong></p><p>数据规模：报告写 SenseVoice 训练超过 30 万小时。Small 的识别延迟陈述为小于 80 ms（报告测试环境），并给出相对 Whisper-small / large 的 5× 与 15× 以上加速。这些是官方吞吐对比，换硬件、换解码器会变。</p><p><span class="marginnote">数字实例感受加速：转写一句 10 秒、约 30 个字的话，自回归若每字要 15 ms，串行就是约 450 ms；非自回归一次前向约 80 ms 出整句——这正是 5 倍量级差距的来源，而且句越长差距越大。</span></p><h3 id="small-是编码器-ctc-large-是编码器—解码器" tabindex="-1">Small 是编码器 CTC，Large 是编码器—解码器 <a class="header-anchor" href="#small-是编码器-ctc-large-是编码器—解码器" aria-label="Permalink to &quot;Small 是编码器 CTC，Large 是编码器—解码器&quot;">​</a></h3><p>Small：只编码器，SAN-M（带记忆的自注意力，Gao et al. 2020）。80 维 log-Mel，连续帧堆叠后时间下采样 6 倍，得到 \\(\\mathbf{X}_{\\mathrm{speech}}\\in\\mathbb{R}^{T\\times D}\\)。输入前拼四个嵌入：语种、情感、音频事件、是否 ITN。输出在对应位置预测标签，ASR 用 CTC。训练时 \\(\\langle\\mathrm{LID}\\rangle\\) 以 0.8 概率换成真值语种，使推理既能自动语种、也能锁语种。Large：类似 Whisper 的自回归编码器—解码器，用解码端 token 序列指定是否预测 LID / SER / 带时间戳的 AED，换准确率与 50+ 语种，放弃 Small 的固定前向延迟。</p><p><span class="marginnote">情感与事件是分类标签，不是开放词汇描述。仓库与博客列出的情绪含 HAPPY / SAD / ANGRY / NEUTRAL / FEARFUL / DISGUSTED / SURPRISED；事件含 Speech / BGM / Applause / Laughter / Cry 等。标签集以卡片为准，不要自行加「讽刺」。</span></p><p><span class="marginnote">CTC 术语翻译：联结时序分类是一种「不用逐帧标注也能训练」的对齐损失——模型在每帧输出字符或 blank，推理时把连续重复折叠、删掉 blank，就得到整句文本。它把「声音和字怎么对上」这个难题交给训练目标自动学。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>前向合同（Small）：波形 → Mel → 下采样 → 拼任务嵌入 → SAN-M → 线性到扩展词表 \\(V&#39;\\)（含 ASR 字与任务标签）→ softmax。LID / SER / AEC 走交叉熵；ASR 走 CTC。ITN 开关决定是否输出规范化数字与标点。FunASR <code>AutoModel</code> 常与 <code>fsmn-vad</code> 组：VAD 切段再送 Small，避免把整小时录音一次性塞进 CTC 对齐。<code>use_itn=True</code> 打开逆文本正则。输出里常见前缀标签如 <code>&lt;|zh|&gt;</code>、<code>&lt;|NEUTRAL|&gt;</code>、<code>&lt;|BGM|&gt;</code>，解析时要剥标签再给下游 LLM。</p><p>Large 的任务指定在解码器端，可要时间戳事件，适合离线精转写。报告 Table 1 用例子对比 Whisper 与 SenseVoice-S/L 的转写风格：Small 更快但错词更多，Large 更贴标点与完整句。不要用单个例子当 WER 表。官方还强调中文与粤语相对 Whisper 的优势——这是报告主张，应用侧应在自己的 AISHELL / Common Voice 切片上复测。</p><h3 id="丰富转写是产品-不是四个独立头的论文创新" tabindex="-1">丰富转写是产品，不是四个独立头的论文创新 <a class="header-anchor" href="#丰富转写是产品-不是四个独立头的论文创新" aria-label="Permalink to &quot;丰富转写是产品，不是四个独立头的论文创新&quot;">​</a></h3><p>把 LID、SER、AED、ITN 放进同一词表，训练目标混合 CE 与 CTC，这是多任务学习。好处是共享声学编码器、标签时间对齐自然。坏处是任务互相抢容量：强噪声下事件标签可能对、字错；纯音乐可能仍被 CTC 逼出幻觉字。FunASR 博客用真实网页片段说明：多数带 BGM 的片子被标 BGM，而 Whisper 倾向硬转写并幻觉——这是定性运维观察，不是论文主表。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>非自回归的延迟机制很简单：输出长度由下采样后的 \\(T\\) 决定，不随字数自回归展开。CTC 允许「blank + 折叠」对齐，不需要音素时长模型。SAN-M 相对纯自注意力，用记忆模块换局部效率，是 FunASR 系 Paraformer 家族的器件，不是 Whisper 的 Transformer 块。下采样 6 把帧率打到可实时；过猛的下采样会伤辅音。四任务嵌入相当于软开关：锁 <code>&lt;|en|&gt;</code> 时模型少做语种搜索，类似 Whisper 锁语言 token。</p><p>Large 回到自回归是因为 CTC 在 50 语种、复杂语法上的对齐更难，解码器可以吃语言先验。这与 Whisper 同构，但词表与任务 token 是 FunAudioLLM 的丰富转写集。SenseVoice 的监督语义被 CosyVoice 拿去当 tokenizer 老师（插 VQ/FSQ），理解模型本身并不输出 codec；不要在 ASR 服务里调用声码器。</p><p><span class="marginnote">报告写 Small 开源、训练与微调代码在 GitHub。商用许可证以 ModelScope / HF 卡片为准，与 FunASR 工具包的 MIT 可能不是同一份。234M 是工具卡数字，写进容量规划可以，写进论文方法学要标明来源。</span></p><p>非自回归为什么快，与自回归对比：</p>',21)),(o(),n(t,null,{default:l(()=>[E(i,{id:"mermaid-61",class:"mermaid",graph:"flowchart%20TD%0A%20%20AR%5B%22%E8%87%AA%E5%9B%9E%E5%BD%92%EF%BC%88Whisper%20%E5%BC%8F%EF%BC%89%22%5D%20--%3E%20S1%5B%22%E7%AC%AC%201%20%E6%AD%A5%EF%BC%9A%E5%87%BA%E7%AC%AC%201%20%E4%B8%AA%E5%AD%97%22%5D%0A%20%20S1%20--%3E%20S2%5B%22%E7%AC%AC%202%20%E6%AD%A5%EF%BC%9A%E7%9C%8B%E5%89%8D%E6%96%87%E5%87%BA%E7%AC%AC%202%20%E4%B8%AA%E5%AD%97%22%5D%0A%20%20S2%20--%3E%20SN%5B%22%E7%AC%AC%20N%20%E6%AD%A5%EF%BC%9A%E9%80%90%E5%AD%97%E4%B8%B2%E8%A1%8C%E5%B1%95%E5%BC%80%22%5D%0A%20%20SN%20--%3E%20LAT1%5B%22%E5%BB%B6%E8%BF%9F%E9%9A%8F%E5%8F%A5%E9%95%BF%E7%BA%BF%E6%80%A7%E6%B6%A8%22%5D%0A%20%20NAR%5B%22%E9%9D%9E%E8%87%AA%E5%9B%9E%E5%BD%92%EF%BC%88Small%EF%BC%89%22%5D%20--%3E%20ONE%5B%22%E4%B8%80%E6%AC%A1%E5%89%8D%E5%90%91%EF%BC%9A%E6%95%B4%E5%8F%A5%E5%B9%B6%E8%A1%8C%E8%BE%93%E5%87%BA%22%5D%0A%20%20ONE%20--%3E%20LAT2%5B%22%E5%BB%B6%E8%BF%9F%E7%94%B1%E4%B8%8B%E9%87%87%E6%A0%B7%E5%90%8E%E5%B8%A7%E6%95%B0%20T%20%E5%86%B3%E5%AE%9A%EF%BC%8C%E4%B8%8E%E5%AD%97%E6%95%B0%E8%A7%A3%E8%80%A6%22%5D%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("p",null,[a("span",{class:"marginnote"},"常见误区：把几小时的播客整段塞给 CTC 模型。CTC 的对齐假设在超长输入上会漂移，输出可能漏句或幻觉。正确姿势是先用 VAD 切成几秒到几十秒的段，再逐段送模型——FunASR 的 fsmn-vad 组合就是干这个的。")],-1)),e[4]||(e[4]=a("h3",{id:"和-whisper-比的是任务集合-不只是-wer",tabindex:"-1"},[s("和 Whisper 比的是任务集合，不只是 WER "),a("a",{class:"header-anchor",href:"#和-whisper-比的是任务集合-不只是-wer","aria-label":'Permalink to "和 Whisper 比的是任务集合，不只是 WER"'},"​")],-1)),e[5]||(e[5]=a("p",null,"Whisper large-v3 强在语种覆盖与翻译；SenseVoice-Small 强在五语种延迟加情感事件。把 Small 换到 50 语种会议上会输给 Large 或 Whisper。把 Whisper 塞进要 80 ms 内出字加情绪的坐席质检，会输给 Small。级联（VAD + Small + LLM）才是 FunAudioLLM 演示里语音翻译、情绪闲聊的形态：理解侧出带标签文本，生成侧交给 CosyVoice。",-1)),(o(),n(t,null,{default:l(()=>[E(i,{id:"mermaid-71",class:"mermaid",graph:"flowchart%20TD%0A%20%20WAV%5B%22%E6%B3%A2%E5%BD%A2%22%5D%20--%3E%20MEL%5B%2280%20%E7%BB%B4%20log-Mel%20%E4%B8%8B%E9%87%87%E6%A0%B7%20%C3%976%22%5D%0A%20%20E1%5B%22LID%20%E5%B5%8C%E5%85%A5%22%5D%20--%3E%20ENC%5B%22SAN-M%20%E7%BC%96%E7%A0%81%E5%99%A8%22%5D%0A%20%20E2%5B%22SER%20%E5%B5%8C%E5%85%A5%22%5D%20--%3E%20ENC%0A%20%20E3%5B%22AEC%20%E5%B5%8C%E5%85%A5%22%5D%20--%3E%20ENC%0A%20%20E4%5B%22ITN%20%E5%BC%80%E5%85%B3%22%5D%20--%3E%20ENC%0A%20%20MEL%20--%3E%20ENC%0A%20%20ENC%20--%3E%20CTC%5B%22CTC%20%E8%BD%AC%E5%86%99%22%5D%0A%20%20ENC%20--%3E%20TAG%5B%22%E8%AF%AD%E7%A7%8D%20%2F%20%E6%83%85%E6%84%9F%20%2F%20%E4%BA%8B%E4%BB%B6%22%5D%0A"})]),fallback:l(()=>[...e[1]||(e[1]=[s(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>Small 不做翻译、不做开放域音频描述。重叠说话要靠外部分离或 CAM++ 日志，不是 SenseVoice 权重内的能力。情感标签文化与语料偏置明显，不能当心理诊断。CTC 无标点时要另开 ITN；ITN 规则偏中文数字习惯。长音频必须 VAD，否则对齐漂移。Large 的 50+ 语种与 Whisper 的语种表不要当成一一对应。</p><p>不要把 SenseVoice 写成 Whisper 蒸馏。不要发明 SAN-M 层数若报告未给。与 <a href="/llm/cosyvoice-2">CosyVoice 2</a> 的耦合是家族设计：2 的 tokenizer 用 Large 前六层，ASR 服务仍应部署独立的 Small/Large 检查点。</p><p><span class="marginnote">出处：Tongyi SpeechTeam，<em>FunAudioLLM: Voice Understanding and Generation Foundation Models for Natural Interaction Between Humans and LLMs</em>，arXiv:2407.04051。仓库 <a href="https://github.com/FunAudioLLM/SenseVoice" target="_blank" rel="noreferrer">https://github.com/FunAudioLLM/SenseVoice</a> ；FunASR 集成见 modelscope/FunASR。演示 <a href="https://fun-audio-llm.github.io" target="_blank" rel="noreferrer">https://fun-audio-llm.github.io</a>。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SenseVoice 是多任务语音理解模型：ASR、LID、情感、音频事件，可选 ITN 与标点。</li><li>Small：SAN-M + CTC，五语种，非自回归低延迟；Large：编码器—解码器，50+ 语种。</li><li>任务由前置（Small）或解码端（Large）特殊 token 指定。</li><li>官方称 Small 相对 Whisper-small / large 有 5× / 15× 以上速度，延迟陈述小于 80 ms。</li><li>开源检查点以 SenseVoice-Small 为主；与 CosyVoice 组成 FunAudioLLM。</li><li>出处：arXiv:2407.04051。</li></ul>',6))])}const D=A(d,[["render",p]]);export{g as __pageData,D as default};
